}): CanonicalClosureParseResult {
  let parsed: unknown;
  try {
    parsed = parseStrictResearchJson(input.bytes);
  } catch (error) {
    return {
      ok: false,
      code: "V13_CLOSURE_SCHEMA_INVALID",
      message:
        error instanceof Error
          ? error.message
          : "Closure artifact is not strict JSON",
    };
  }
  if (!isRecord(parsed)) {
    return {
      ok: false,
      code: "V13_CLOSURE_SCHEMA_INVALID",
      message: "Closure artifact must be an object",
    };
  }
